@Component
struct RetryBadge {
 @State notice: string = ''
 build() {
  Button('Retry delivery').onClick(() => { this.notice = 'retry status updated' })
 }
}

struct RestoreView {
  @State retryAllowed: boolean = false
  @State notice: string = ''
  enableCapacityRecovery(): void {
    this.retryAllowed = true
    this.notice = 'capacity recovery available'
  }
  build() {
    Button('Restore capacity').onClick(() => this.enableCapacityRecovery())
    Text(this.notice)
  }
}

import { RestoreView } from '../ui/RestoreView'
export function registerScreens(): string {
 return 'retry notice registry'
}

